
import { ISessionManagementEvents, ISessionModel } from '@game-studio/overlays';
import { IGameServerResponse, ISubGameSessionInfo, RESULT_CODES } from '@game-studio/server-comms';
import axios from 'axios';
import EventEmitter from 'eventemitter3';
import { defineComponent } from 'vue';
import { gameConfig } from '../../models/config-model';
import { inversifyContainer } from '../../inversify/container';
import { sessionDataModel } from '../../models/session-data';
import { userModel } from '../../models/user';
import { device } from '../../services/device';
import { environment } from '../../services/environment';
import { eventEmitter } from '../../services/event-emitter';
import { queryStringParams } from '../../services/query-string';
import { ICreateSessionData } from '../../types';

// TODO: add additional htp slide...
export default defineComponent({
    name: 'SessionView',
    components: {
    },
    props: {
        viewHeight: { type: Number, required: true },
    },
    data() {
        return {
            config: {
                crossCheck: userModel.crossCheck,
                userId: userModel.userId,
                translations: inversifyContainer.strings.sessionManager,
                minStake: 200,
                currency: inversifyContainer.currencySettings,
                sessionEndedWindow: 3600,
                debugSessionValues: false
            },
            sessionModel: sessionDataModel,
            userModel: userModel,
            sessionEvents: new EventEmitter<ISessionManagementEvents>(),
            sessionRequestInProgress: false,
            isGameInProgress: inversifyContainer.gameModel.isInProgress,
            inlineStyle:
                { '--sessionManagementBottom': `${window.innerHeight - this.viewHeight}px` }
        };
    },
    computed: {
        hasLowBalance(): boolean { return userModel.visibleBalance.endBalance < inversifyContainer.stake.lowestStake; },
        hasFreeplayBalance(): boolean { return userModel.freePlayBalance > 0 && gameConfig.supportsFreeplays; }
    },
    mounted(): void {
        this.setupSessionConfig();
        this.setupEvents();

        this.$nextTick(() => {
            if (queryStringParams.isSubGame) {
                this.sessionEvents.emit('session:form:hide');
            }
        });
    },
    methods: {
        externalPageNavigation(url: string): void {
            if (url.startsWith('http')) {
                inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'navigation', data: { type: 'url', location: url } });
            } else {
                // If the url does not start with http, we assume it's a relative path
                const fullUrl = `${inversifyContainer.endPoints.urls[environment].platform}${url}`;
                inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'navigation', data: { type: 'url', location: fullUrl } });
            }
        },
        sessionDidNotEndRecently(): boolean {
            const sixtyMinutes = 3600;
            if (sessionDataModel.status.SessionEnded && sessionDataModel.status.SessionId > 0) {
                const timeSinceSessionEnded = sessionDataModel.status.CurrentTime - sessionDataModel.status.MaxTime;
                if (timeSinceSessionEnded < sixtyMinutes) {
                    return false;
                }
            }
            return true;
        },
        setupSessionConfig(): void {
            this.config = {
                crossCheck: userModel.crossCheck,
                userId: userModel.userId,
                translations: inversifyContainer.strings.sessionManager,
                minStake: inversifyContainer.stake.lowestStake,
                currency: inversifyContainer.currencySettings,
                sessionEndedWindow: 3600,
                debugSessionValues: (environment === 'debug' || environment === 'dev')
            };
        },
        setupEvents(): void {
            this.sessionEvents.on('session:create', this.onSessionCreate, this);
            this.sessionEvents.on('session:ended', this.onSessionEnded, this);
            this.sessionEvents.on('session:reset', this.onSessionEnded, this);
            this.sessionEvents.on('session:closed', this.onSessionClosed, this);
            this.sessionEvents.on('session:ended:closed', (response?: ISubGameSessionInfo) => {
                this.onSessionEndedClosed(response);
            });

            eventEmitter.on('GAME_COMPLETE', () => {
                this.isGameInProgress = false;
            });
            eventEmitter.on('GAME_BEGIN', () => {
                this.isGameInProgress = true;
            });

            eventEmitter.on('POPUP_SHOW_SESSION', (response) => {
                this.showForm(response);
            });

            eventEmitter.on('POPUP_HIDE_SESSION', () => {
                this.sessionEvents.emit('session:form:hide');
            });

            eventEmitter.on('GLOBAL_SETTINGS_VISIBILITY_CHANGE', (visibility: boolean) => {
                if (visibility) {
                    this.sessionEvents.emit('session:form:hide');
                }
            });
        },
        setSessionFullScreen(): void {
            this.$nextTick(() => {
                this.$forceUpdate();
            });

            if (device.type.isDesktop) {
                return;
            }
            // device.addOverlayItem('spain-session');
        },
        showForm(response: ISubGameSessionInfo): void {
            if (queryStringParams.isSubGame) {
                inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'session-manager', data: response });
                return;
            }

            this.setSessionFullScreen();
            this.sessionEvents.emit('session:form:show', response);
        },
        removeFullScreenForm(): void {
            if (!this.sessionRequestInProgress) {
                // device.removeOverlayItem('spain-session');
            }
            this.$nextTick(() => {
                this.$forceUpdate();
            });
        },
        onSessionEnded(): void {
            Object.assign(sessionDataModel.status.SessionEnded, true);
        },
        onSessionClosed(): void {
            this.removeFullScreenForm();
        },
        onSessionEndedClosed(response?: ISubGameSessionInfo): void {
            if (this.sessionDidNotEndRecently()) {
                this.setSessionFullScreen();
                this.sessionEvents.emit('session:form:show', response);
            }
        },
        async onSessionCreate(model: ISessionModel): Promise<void> {
            if (this.sessionRequestInProgress) {
                return;
            }
            this.sessionRequestInProgress = true;

            let data: ICreateSessionData = {
                UserId: userModel.userId,
                CrossCheck: userModel.crossCheck,
                ClientTypeId: userModel.clientTypeId,
                Skin: gameConfig.engineName === 'unknown' ? 'bubble' : gameConfig.engineSkinName,
                MaxBet: model.maxBet,
                MaxTime: model.maxTime,
                AlertFrequency: model.alertFrequency,
                SessionRestriction: model.sessionRestriction
            };

            if (userModel.freePlayBalance > 0) {
                let maxBetAmount = 0;

                // Opening an ES session with maxBet 0 creates a freeplay session. Once a user tries to spend real money they are prompted to create another session.
                switch (queryStringParams.locale) {
                    case 'it-it':
                        maxBetAmount = userModel.freePlayBalance;
                        break;
                    case 'es-es':
                    default:
                        maxBetAmount = 0;
                        break;
                }
                data = { ...data, PlayMode: 'FreePlay', MaxBet: maxBetAmount };
            }

            try {
                let response = (await axios.post<IGameServerResponse>((`${inversifyContainer.endPoints.urls[environment].game}${'createsession'}`), data)).data;
                if (response.ResultCode?.ResultCode === RESULT_CODES.INTERNATIONAL_SESSION_ALREADY_EXISTS) {
                    response = await inversifyContainer.gameServer.resumeRequest(gameConfig.engineSkinName);
                    // inversifyContainer.frameConnection.operator.onError(response.ResultCode);
                }
                this.sessionRequestInProgress = false;
                this.removeFullScreenForm();
                eventEmitter.emit('GLOBAL_SESSION_CREATED', response);
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
            } catch (error: any) {
                this.sessionRequestInProgress = false;
                this.removeFullScreenForm();
                const resultCode = error.ResultCode?.ResultCode;
                if (resultCode === RESULT_CODES.NOT_AUTHORISED) {
                    inversifyContainer.frameConnection.operator.onError(resultCode);
                    return;
                }
                // inversifyContainer.frameConnection.onException('Exception.SessionManagement', resultCode);
            }
        }
    }
});
